export function renderTemplate(templateId, vars = {}) {
  const t = NOTIFICATION_TEMPLATES.find((x) => x.id === templateId);
  if (!t) return null;
  let subject = t.subject;
  let body = t.body;
  for (const [k, v] of Object.entries(vars)) {
    subject = subject.replaceAll(`{{${k}}}`, String(v));
    body = body.replaceAll(`{{${k}}}`, String(v));
  }
  return { channel: t.channel, subject, body };
}
